import{_ as a,o as t,c as o,a6 as r}from"./chunks/framework.mtgKxyez.js";const p=JSON.parse('{"title":"3. More Competition Details","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced/3.md","filePath":"en/advanced/3.md"}'),i={name:"en/advanced/3.md"};function n(s,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-more-competition-details" tabindex="-1">3. More Competition Details <a class="header-anchor" href="#_3-more-competition-details" aria-label="Permalink to &quot;3. More Competition Details&quot;">​</a></h1><h2 id="dorm-experience" tabindex="-1">Dorm Experience <a class="header-anchor" href="#dorm-experience" aria-label="Permalink to &quot;Dorm Experience&quot;">​</a></h2><p>The dorm is basically the dormitory of Taichung Industrial High School. The rooms have bunk beds with desks below and beds above. Since not many teams enter the camp, it is usually one team per room. The room equipment is decent: outlets, desks, a balcony with a sink, and fairly spacious room. Sleep quality is not ideal. Before the competition, they only ask you to bring a sleeping bag, but sleeping in a sleeping bag on a bed board feels basically the same as sleeping directly on the bed board. It is extremely hard. If possible, bring a few extra blankets as padding.</p><h2 id="practice-and-rest-time" tabindex="-1">Practice and Rest Time <a class="header-anchor" href="#practice-and-rest-time" aria-label="Permalink to &quot;Practice and Rest Time&quot;">​</a></h2><p>Every day after class and before dinner, and after dinner before returning to the dorm, is free practice time. During this time, you can practice that day&#39;s content with your teammate. After you are truly familiar with it, you can add extra creative ideas yourself and combine things you want to learn with things you already learned. That helps you learn how to use different functions in projects faster.</p><p>For rest, before returning to the dorm, camp staff usually take everyone to a nearby PX Mart. You can buy snacks and drinks there and bring them back to the dorm for the night.</p><h2 id="software-updates" tabindex="-1">Software Updates <a class="header-anchor" href="#software-updates" aria-label="Permalink to &quot;Software Updates&quot;">​</a></h2><p>TM Robot software used to update quite often. Updates may remove or add functions, or even change the UI, so pay special attention to this. If the camp uses a new version, spend time getting familiar with it so you have better confidence by finals.</p>',8)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
